    }

    .signup-prompt-toast {
        left: var(--space-4);
        right: var(--space-4);
        bottom: var(--space-20);
    }

    .event-detail-card {
        padding: var(--space-5);
    }

    .event-detail__hero {
        margin: calc(-1 * var(--space-5));
        margin-bottom: var(--space-5);
        padding: var(--space-6);
    }

    .event-detail__menu-grid {
        grid-template-columns: 1fr;
    }

    .event-detail__title {
        font-size: 1.75rem;
    }

    .event-detail__hours {
        margin-top: var(--space-4);
    }

    .event-detail__hours > .event-detail__hours-pills {
        display: none;
