{% extends "regions/base_public.html" %}
{% load static %}
{% load region_extras %}

{% block extra_js %}
<script>
// Analytics beacon - runs on every page load (even cached pages)
(function() {
    var beacon = new Image();
    beacon.src = '{% url "regions:track_view" slug=region.slug %}?stage=REGION_VIEW&_=' + Date.now();
})();
</script>
{% endblock %}

{% block structured_data %}
{% include "regions/partials/_structured_data.html" with region=region events=events description=page_meta.meta_description %}
{% endblock %}

{% block content %}
<div class="region-page">
    {# Hero Section #}
    <section class="region-hero" style="--hero-image: url('{{ region.hero_image_url|default:"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1600" }}');">
        <div class="region-hero__overlay"></div>
        <div class="region-hero__content">
            <nav class="region-breadcrumb">
                <a href="{% url 'regions:explore' %}">Explore</a>
                <span class="separator">/</span>
                <span class="current">{{ region.name }}</span>
            </nav>
            <h1 class="region-hero__title">{{ region.tagline|default:region.name }}</h1>
            <p class="region-hero__subtitle">{{ total_events }} upcoming events</p>
            <div class="region-hero__cta">
                <a href="{{ region.get_specials_today_url }}" class="btn btn-outline-light btn-lg">
                    Today's Specials
                </a>
                <a href="{% url 'account_signup' %}?region={{ region.id }}" class="btn btn-primary btn-lg">
                    Plan a Trip
                </a>
            </div>
        </div>
    </section>

    {# Region Description #}
    {% if region.description %}
    <section class="region-about">
        <div class="container">
            <div class="row justify-content-center">
                <div class="col-lg-8">
                    <div class="about-content">
                        <h2>About {{ region.name }}</h2>
                        <p>{{ region.description }}</p>
                    </div>
                </div>
            </div>
        </div>
    </section>
    {% endif %}

    {# Filters #}
    <section class="events-filters">
        <div class="container">
            {# Area Filter #}
            {% if areas %}
            <div class="filter-group">
                <label class="filter-label">Location</label>
                <div class="area-filters">
                    <a href="{{ url_all_areas }}"
                       class="area-filter {% if not selected_area %}active{% endif %}">
                        All Towns
                    </a>
                    {% for area in areas %}
                    <a href="{{ area_urls|lookup:area.id }}"
                       class="area-filter {% if selected_area == area.id|stringformat:'s' %}active{% endif %}">
                        {{ area.name|strip_area }}
                    </a>
                    {% endfor %}
                </div>
            </div>
            {% endif %}

            {# Category Filter #}
            <div class="filter-group">
                <label class="filter-label">Category</label>
                <div class="category-filters">
                    <a href="{{ url_all_categories }}"
                       class="category-filter {% if not selected_category %}active{% endif %}">
                        All Categories
                    </a>
                    {% for category_code, category_name in categories %}
                    <a href="{{ category_urls|lookup:category_code }}"
                       class="category-filter {% if selected_category == category_code %}active{% endif %}">
                        {{ category_name }}
                    </a>
                    {% endfor %}
                </div>
            </div>
        </div>
    </section>

    {# Calendar #}
    <section class="events-calendar-section">
        <div class="container">
            {% include "regions/partials/_calendar_grid.html" %}
        </div>
    </section>

    {# View Toggle & Events #}
    <section class="events-grid">
        <div class="container">
            {# List / Map Toggle #}
            {% if map_points %}
            <div class="view-toggle">
                <button type="button" class="view-toggle__btn view-toggle__btn--active" data-view="list">
                    <i class="bi bi-list-ul"></i> List
                </button>
                <button type="button" class="view-toggle__btn" data-view="map">
                    <i class="bi bi-geo-alt"></i> Map
                </button>
            </div>
            {% endif %}

            {# List View #}
            <div id="events-list-view">
                <div class="row g-4">
                    {% for event in events %}
                    <div class="col-md-6 col-lg-4">
                        {% include "regions/partials/_event_card.html" with event=event %}
                    </div>
                    {% empty %}
                    <div class="col-12">
                        <div class="empty-state">
                            <i class="bi bi-calendar-x"></i>
                            <p>No events found matching your filters.</p>
                            <a href="{% url 'regions:region_detail' slug=region.slug %}" class="btn btn-primary">
                                View All Events
                            </a>
                        </div>
                    </div>
                    {% endfor %}
                </div>

                {# Pagination #}
                {% if total_pages > 1 %}
                <nav class="pagination-wrapper">
                    <ul class="pagination justify-content-center">
                        {% if has_previous %}
                        <li class="page-item">
                            <a class="page-link" href="?page={{ previous_page }}{% if selected_category %}&category={{ selected_category }}{% endif %}{% if selected_area %}&area={{ selected_area }}{% endif %}{% if selected_date %}&date={{ selected_date }}{% endif %}{% if selected_month %}&month={{ selected_month }}{% endif %}">
                                <i class="bi bi-chevron-left"></i> Previous
                            </a>
                        </li>
                        {% endif %}

                        <li class="page-item disabled">
                            <span class="page-link">
                                Page {{ page }} of {{ total_pages }}
                            </span>
                        </li>

                        {% if has_next %}
                        <li class="page-item">
                            <a class="page-link" href="?page={{ next_page }}{% if selected_category %}&category={{ selected_category }}{% endif %}{% if selected_area %}&area={{ selected_area }}{% endif %}{% if selected_date %}&date={{ selected_date }}{% endif %}{% if selected_month %}&month={{ selected_month }}{% endif %}">
                                Next <i class="bi bi-chevron-right"></i>
                            </a>
                        </li>
                        {% endif %}
                    </ul>
                </nav>
                {% endif %}
            </div>

            {# Map View #}
            {% if map_points %}
            <div id="events-map-view" style="display:none">
                <div id="region-map" class="region-map" aria-label="Map of event locations"></div>
            </div>
            {{ map_points|json_script:"region-map-data" }}
            {% endif %}
        </div>
    </section>

    {# CTA Section #}
    {% include "regions/partials/_cta_signup.html" with region=region %}
</div>

{% if map_points %}
<script>
window.__regionGoogleMapsLoaded = window.__regionGoogleMapsLoaded || false;
window.initRegionGoogleMap = function() {
    window.__regionGoogleMapsLoaded = true;
    if (typeof window.__renderRegionGoogleMap === 'function') {
        window.__renderRegionGoogleMap();
    }
};

document.addEventListener('DOMContentLoaded', function() {
    var toggleBtns = document.querySelectorAll('.view-toggle__btn');
    var listView = document.getElementById('events-list-view');
    var mapView = document.getElementById('events-map-view');
    var mapInstance = null;
    var mapBounds = null;
    var infoWindow = null;

    function escapeHtml(value) {
        return String(value || '').replace(/[&<>"']/g, function(char) {
            return {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#39;'
            }[char];
        });
    }

    function buildMarkerIcon(fillColor, scale, strokeWeight) {
        return {
            path: google.maps.SymbolPath.CIRCLE,
            fillColor: fillColor,
            fillOpacity: 0.92,
            strokeColor: '#ffffff',
            strokeOpacity: 1,
            strokeWeight: strokeWeight,
            scale: scale
        };
    }

    function initMap() {
        if (mapInstance) {
            return mapInstance;
        }

        var mapEl = document.getElementById('region-map');
        var dataEl = document.getElementById('region-map-data');
        if (!mapEl || !dataEl || !window.__regionGoogleMapsLoaded || !(window.google && google.maps)) {
            return null;
        }

        var points = JSON.parse(dataEl.textContent || '[]');
        if (!Array.isArray(points) || points.length === 0) {
            return null;
        }

        mapInstance = new google.maps.Map(mapEl, {
            mapTypeControl: false,
            streetViewControl: false,
            fullscreenControl: true,
            zoomControl: true,
            gestureHandling: 'cooperative'
        });
        infoWindow = new google.maps.InfoWindow();
        mapBounds = new google.maps.LatLngBounds();

        points.forEach(function(point) {
            var marker = new google.maps.Marker({
                map: mapInstance,
                position: { lat: point.latitude, lng: point.longitude },
                title: point.venue_label,
                icon: buildMarkerIcon('#45B7D1', 9, 2)
            });

            var eventList = point.event_names.map(function(name, index) {
                var url = point.event_urls[index];
                return '<li><a href="' + escapeHtml(url) + '">' + escapeHtml(name) + '</a></li>';
            }).join('');

            var directions = point.google_maps_uri
                ? '<a class="region-map-popup__link" href="' + escapeHtml(point.google_maps_uri) + '" target="_blank" rel="noopener">Open in Google Maps</a>'
                : '';

            marker.addListener('click', function() {
                infoWindow.setContent(
                    '<div class="region-map-popup">' +
                    '<div class="region-map-popup__venue">' + escapeHtml(point.venue_label) + '</div>' +
                    (point.address ? '<div class="region-map-popup__address">' + escapeHtml(point.address) + '</div>' : '') +
                    '<ul class="region-map-popup__list">' + eventList + '</ul>' +
                    (directions ? '<div class="region-map-popup__actions">' + directions + '</div>' : '') +
                    '</div>'
                );
                infoWindow.open({ anchor: marker, map: mapInstance });
            });

            mapBounds.extend(marker.getPosition());
        });

        if (points.length === 1) {
            mapInstance.setCenter({ lat: points[0].latitude, lng: points[0].longitude });
            mapInstance.setZoom(13);
        } else {
            mapInstance.fitBounds(mapBounds, 48);
        }

        return mapInstance;
    }

    function refreshMapLayout() {
        if (!mapInstance || !(window.google && google.maps)) {
            return;
        }

        var center = mapInstance.getCenter();
        google.maps.event.trigger(mapInstance, 'resize');
        if (center) {
            mapInstance.setCenter(center);
        }
        if (mapBounds && !mapBounds.isEmpty()) {
            mapInstance.fitBounds(mapBounds, 48);
        }
    }

    toggleBtns.forEach(function(btn) {
        btn.addEventListener('click', function() {
            var view = btn.dataset.view;
            toggleBtns.forEach(function(button) {
                button.classList.remove('view-toggle__btn--active');
            });
            btn.classList.add('view-toggle__btn--active');

            if (view === 'map') {
                listView.style.display = 'none';
                mapView.style.display = 'block';
                if (initMap()) {
                    setTimeout(refreshMapLayout, 120);
                }
            } else {
                mapView.style.display = 'none';
                listView.style.display = 'block';
            }
        });
    });

    window.__renderRegionGoogleMap = function() {
        if (mapView && mapView.style.display === 'block' && initMap()) {
            setTimeout(refreshMapLayout, 120);
        }
    };
});
</script>
<script async
        src="https://maps.googleapis.com/maps/api/js?key={{ google_maps_api_key|urlencode }}&callback=initRegionGoogleMap&loading=async"></script>
{% endif %}
{% endblock %}

