}', 'originalFile': '/**
 * Regional Calendar - Editorial Design System
 *
 * Aesthetic: Coastal Editorial - Magazine meets travel guide
 * Typography: Playfair Display (display) + System Stack (body)
 * Colors: Teal ocean (#45B7D1) + Warm sand (#f5e6d3)
 */

/* ============================================
   CSS Custom Properties - Design Tokens
   ============================================ */
:root {
    /* Typography */
    --font-display: 'Playfair Display', Georgia, serif;
    --font-body: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;

    /* Colors - Coastal Palette */
    --color-ocean: #45B7D1;
    --color-ocean-dark: #3AA3BD;
    --color-ocean-light: #6EC8DD;
    --color-sand: #f5e6d3;
    --color-sand-dark: #e6d4be;
    --color-driftwood: #8B7355;
    --color-sunset: #FF6B6B;
    --color-seafoam: #88D8B0;

    /* Neutral Scale */
    --color-white: #ffffff;
    --color-gray-50: #f9fafb;
    --color-gray-100: #f3f4f6;
    --color-gray-200: #e5e7eb;
    --color-gray-300: #d1d5db;
    --color-gray-400: #9ca3af;
    --color-gray-500: #6b7280;
    --color-gray-600: #4b5563;
    --color-gray-700: #374151;
    --color-gray-800: #1f2937;
    --color-gray-900: #111827;

    /* Spacing Scale */
    --space-1: 0.25rem;
    --space-2: 0.5rem;
    --space-3: 0.75rem;
    --space-4: 1rem;
    --space-5: 1.25rem;
    --space-6: 1.5rem;
    --space-8: 2rem;
    --space-10: 2.5rem;
    --space-12: 3rem;
    --space-16: 4rem;
    --space-20: 5rem;
    --space-24: 6rem;

    /* Border Radius */
    --radius-sm: 0.25rem;
    --radius-md: 0.5rem;
    --radius-lg: 0.75rem;
    --radius-xl: 1rem;
    --radius-2xl: 1.5rem;
    --radius-full: 9999px;

    /* Shadows */
    --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
    --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
    --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
    --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);

    /* Transitions */
    --transition-fast: 150ms ease;
    --transition-normal: 300ms ease;
    --transition-slow: 500ms ease;
}


/* ============================================
   Base Styles
   ============================================ */
.regions-public {
    font-family: var(--font-body);
    color: var(--color-gray-800);
    background-color: var(--color-white);
    line-height: 1.6;
    padding-top: 0;
}

.regions-public h1,
.regions-public h2,
.regions-public h3,
.regions-public h4 {
    font-family: var(--font-display);
    font-weight: 600;
    line-height: 1.2;
    color: var(--color-gray-900);
}


/* ============================================
   Navigation
   ============================================ */
.regions-navbar {
    background: var(--color-white);
    border-bottom: 1px solid var(--color-gray-200);
    padding: 0;
    position: sticky;
    top: 0;
    z-index: 1000;
}

.regions-navbar > .container.regions-navbar__inner {
    min-height: 4rem;
    padding: var(--space-1) var(--space-4);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-4);
}

.regions-navbar__brand {
    padding: 0;
    margin: 0;
    display: inline-flex;
    align-items: center;
    min-height: auto;
    white-space: nowrap;
}

.regions-navbar__brand.navbar-brand {
    font-size: var(--font-size-xl);
    line-height: 1;
}

.regions-navbar__actions {
    align-items: center;
    gap: var(--space-2);
    flex-wrap: wrap;
    row-gap: var(--space-2);
}

.regions-navbar .nav-link {
    font-weight: 500;
    color: var(--color-gray-600);
    padding: var(--space-1) var(--space-3);
    min-height: 2.25rem;
    display: inline-flex;
    align-items: center;
    border-radius: var(--radius);
    transition: color var(--transition-fast), background-color var(--transition-fast);
}

.regions-navbar .nav-link:hover,
.regions-navbar .nav-link.active {
    color: var(--color-ocean);
    background: rgba(69, 183, 209, 0.08);
}

.regions-navbar__cta {
    min-height: 2.25rem;
    padding: 0.5rem 0.9rem;
    display: inline-flex;
    align-items: center;
}

@media (max-width: 768px) {
    .regions-navbar > .container.regions-navbar__inner {
        padding: var(--space-1) var(--space-3);
        gap: var(--space-3);
    }

    .regions-navbar__brand.navbar-brand {
        font-size: 1.05rem;
    }

    .regions-navbar__actions {
        gap: var(--space-1);
        justify-content: flex-end;
    }

    .regions-navbar .nav-link,
    .regions-navbar__cta {
        min-height: 2.25rem;
    }
}


/* ============================================
   Hero Sections
   ============================================ */

/* Explore Page Hero */
.explore-hero {
    min-height: 50vh;
    background:
        linear-gradient(135deg, rgba(69, 183, 209, 0.9) 0%, rgba(139, 115, 85, 0.8) 100%),
        url('https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1600') center/cover;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    color: var(--color-white);
}

.explore-hero__overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.4) 100%);
}

.explore-hero__content {
    position: relative;
    z-index: 1;
    padding: var(--space-8) var(--space-6);
}

.explore-hero__badge {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    background: rgba(255,255,255,0.2);
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    margin-bottom: var(--space-4);
}

.explore-hero__title {
    font-family: var(--font-display);
    font-size: clamp(2.5rem, 6vw, 4rem);
    font-weight: 700;
    color: var(--color-white);
    margin-bottom: var(--space-4);
    text-shadow: 0 2px 20px rgba(0,0,0,0.3);
}

.explore-hero__subtitle {
    font-size: 1.25rem;
    opacity: 0.9;
    max-width: 600px;
    margin: 0 auto;
}

/* Region Detail Hero */
.region-hero {
    min-height: clamp(280px, 42vh, 440px);
    background: var(--hero-image, linear-gradient(135deg, var(--color-ocean), var(--color-driftwood))) center/cover;
    position: relative;
    display: flex;
    align-items: flex-end;
    color: var(--color-white);
}

.region-hero__overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(0,0,0,0.25) 0%, rgba(0,0,0,0.8) 100%);
}

.region-hero__content {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--space-8) var(--space-6);
}

.region-hero__title {
    font-family: var(--font-display);
    font-size: clamp(2rem, 6vw, 3.25rem);
    font-weight: 700;
    color: var(--color-white);
    margin-bottom: var(--space-2);
    text-shadow: 0 2px 30px rgba(0,0,0,0.4);
}

.region-hero__subtitle {
    font-size: 1.25rem;
    opacity: 0.9;
    margin-bottom: var(--space-6);
}

.region-hero__cta {
    display: flex;
    gap: var(--space-4);
    flex-wrap: wrap;
}

/* Breadcrumb */
.region-breadcrumb {
    font-size: 0.875rem;
    margin-bottom: var(--space-4);
    opacity: 0.8;
}

.region-breadcrumb a {
    color: inherit;
    text-decoration: none;
}

.region-breadcrumb a:hover {
    text-decoration: underline;
}

.region-breadcrumb .separator {
    margin: 0 var(--space-2);
    opacity: 0.5;
}

.region-breadcrumb .current {
    opacity: 0.7;
}


/* ============================================
   Specials Pages
   ============================================ */
.specials-hero {
    min-height: clamp(360px, 52vh, 560px);
    background: var(--hero-image, linear-gradient(135deg, var(--color-ocean), var(--color-driftwood))) center/cover;
    color: var(--color-white);
    position: relative;
    display: flex;
    align-items: stretch;
}

.specials-hero__overlay {
    position: absolute;
    inset: 0;
    background:
        linear-gradient(100deg, rgba(11, 20, 28, 0.88) 0%, rgba(11, 20, 28, 0.72) 38%, rgba(11, 20, 28, 0.35) 72%, rgba(11, 20, 28, 0.2) 100%),
        linear-gradient(180deg, rgba(11, 20, 28, 0.45) 0%, rgba(11, 20, 28, 0.35) 40%, rgba(11, 20, 28, 0.85) 100%);
}

.specials-hero__content {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--space-6) var(--space-6) clamp(var(--space-8), 6vh, var(--space-12));
    display: grid;
    grid-template-rows: auto 1fr auto;
    gap: 0;
}

.specials-hero .region-breadcrumb {
    margin-bottom: 0;
    align-self: start;
}

.specials-hero__heading {
    align-self: end;
    max-width: 48rem;
}

.specials-hero__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.28);
    border-radius: var(--radius-full);
    padding: var(--space-2) var(--space-4);
    margin-bottom: var(--space-5);
    backdrop-filter: blur(6px);
}

.specials-hero .specials-hero__title {
    color: var(--color-white);
    font-size: clamp(2rem, 5.2vw, 3.75rem);
    font-weight: 700;
    line-height: 1.05;
    letter-spacing: -0.01em;
    max-width: 22ch;
    margin-bottom: var(--space-3);
    text-shadow:
        0 0 2px rgba(0, 0, 0, 0.9),
        0 2px 6px rgba(0, 0, 0, 0.85),
        0 6px 24px rgba(0, 0, 0, 0.6);
}

.specials-hero__subtitle {
    font-size: clamp(1rem, 1.3vw, 1.125rem);
    line-height: 1.5;
    opacity: 0.92;
    max-width: 52ch;
    margin-bottom: 0;
}

.specials-hero__controls {
    margin-top: clamp(var(--space-6), 5vh, var(--space-10));
    display: flex;
    flex-direction: column;
    gap: var(--space-4);
}

.specials-topbar {
    background: var(--color-warm-sand, #faf7f2);
    border-bottom: 1px solid rgba(0, 0, 0, 0.06);
    padding: var(--space-3) 0;
}

.specials-topbar__inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--space-6);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-4);
}

.specials-topbar__text {
    font-size: 0.9rem;
    color: var(--gray-600, #4b5563);
    font-weight: 500;
}

.specials-topbar__actions {
    display: flex;
    gap: var(--space-2);
    flex-shrink: 0;
}

.specials-toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-3);
}

.specials-filters {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
}

.specials-filters__chip {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    background: rgba(255, 255, 255, 0.14);
    color: var(--color-white);
    border: 1px solid rgba(255, 255, 255, 0.22);
    font-weight: 600;
    text-decoration: none;
    transition: background-color 0.2s ease, transform 0.2s ease;
}

.specials-filters__chip:hover,
.specials-filters__chip--active {
    background: rgba(255, 255, 255, 0.92);
    color: var(--color-ocean-dark);
}

.specials-toolbar__link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    text-decoration: none;
    color: var(--color-white);
    padding: var(--space-3) var(--space-4);
    border-radius: var(--radius-full);
    background: rgba(255, 255, 255, 0.12);
    border: 1px solid rgba(255, 255, 255, 0.2);
    transition: transform var(--transition-fast), background var(--transition-fast);
}

.specials-toolbar__link:hover {
    color: var(--color-white);
    transform: translateY(-1px);
    background: rgba(255, 255, 255, 0.2);
}

.specials-toolbar__link--primary {
    background: var(--color-sunset);
    border-color: transparent;
}

.specials-toolbar__link--copied {
    background: rgba(136, 216, 176, 0.24);
    border-color: rgba(136, 216, 176, 0.65);
}

.specials-listing {
    background:
        radial-gradient(circle at top right, rgba(136, 216, 176, 0.15), transparent 40%),
        linear-gradient(180deg, #fffefb 0%, #f7fafb 100%);
    padding: var(--space-12) 0 var(--space-20);
}

.specials-layout {
    display: block;
}

.specials-layout--with-map {
    display: grid;
    gap: var(--space-6);
}

.specials-map-panel {
    min-width: 0;
}

.specials-map-card {
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(255, 255, 255, 0.98));
