    display: grid;
    grid-template-rows: auto 1fr auto;
    gap: 0;
}

.specials-hero .region-breadcrumb {
    margin-bottom: 0;
    align-self: start;
}

.specials-hero__heading {
    align-self: end;
    max-width: 48rem;
}

.specials-hero__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-size: 0.72rem;
    font-weight: 700;
